    /**
     * Lazily initializes and returns the country data map.
     *
     * @return array<string, array{name: string, scope: string, type: string, iso639_1: string, iso639_2_b: string, iso639_2_t: string, iso639_3: string, iso639_5: string, alternate_names: array<string>}>
     */
    private static function languageData(): array
    {
        // Define arrow function to extract language data from LanguageInfo
        // attributes into an associative array
        $dataExtractor = fn ($info, $caseValue) => [
            'name' => $info->name,
            'scope' => $info->scope,
            'type' => $info->type,
            'iso639_1' => $info->iso639_1,
            'iso639_2_b' => $info->iso639_2_b,
            'iso639_2_t' => $info->iso639_2_t,
            'iso639_3' => $info->iso639_3,
            'iso639_5' => $info->iso639_5,
            'alternate_names' => $info->alternate_names,
        ];

        // Build and cache the lazy data map using reflection to extract
        // LanguageInfo attributes from all enum cases
        $result = EnumDataUtils::buildLazyDataMap(
            self::class,
            LanguageInfo::class,
            $dataExtractor
        );

        // Clean up variables to free up memory
        unset(
            $dataExtractor
        );

        // Return the cached language data map
        return $result;
    }

    /**
     * Get the English name of the language.
     *
     * @return string The English name of the language
     */
    public function name(): string
    {
        // Retrieve the cached language data map
        $data = self::languageData();

        // Extract and return the name field value for this language
        return EnumDataUtils::getFieldValue(
            $data,
            $this->value,
            'name',
            'language'
        );
    }

